"""Regenerate the broken test maps in tests/fixtures/maps/ from maps/test_box.

Usage: python tests/fixtures/generate.py
Each fixture breaks exactly one thing; tests/test_validate.py asserts the validator names it.
"""

from __future__ import annotations

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SRC = ROOT / "maps" / "test_box" / "src" / "test_box.map"
OUT = Path(__file__).resolve().parent / "maps"

VALIDATE_YAML = "rules:\n  spawns_per_team: 2\n"


def box(
    lo: tuple[int, int, int], hi: tuple[int, int, int], tex: str, flip_top: bool = False
) -> str:
    """Axis-aligned box brush in Valve 220 (same face order/convention as test_box.map)."""
    (x0, y0, z0), (x1, y1, z1) = lo, hi
    d = 16
    faces = [
        ((x0, y0, z0), (x0, y0 + d, z0), (x0, y0, z0 + d), "[ 0 -1 0 0 ] [ 0 0 -1 0 ]"),
        ((x0, y0, z0), (x0, y0, z0 + d), (x0 + d, y0, z0), "[ 1 0 0 0 ] [ 0 0 -1 0 ]"),
        ((x0, y0, z0), (x0 + d, y0, z0), (x0, y0 + d, z0), "[ -1 0 0 0 ] [ 0 -1 0 0 ]"),
        ((x1, y1, z1), (x1, y1 + d, z1), (x1 + d, y1, z1), "[ 1 0 0 0 ] [ 0 -1 0 0 ]"),
        ((x1, y1, z1), (x1 + d, y1, z1), (x1, y1, z1 + d), "[ -1 0 0 0 ] [ 0 0 -1 0 ]"),
        ((x1, y1, z1), (x1, y1, z1 + d), (x1, y1 + d, z1), "[ 0 1 0 0 ] [ 0 0 -1 0 ]"),
    ]
    if flip_top:  # reverse the winding of the top face: its normal now points into the brush
        a, b, c, ax = faces[3]
        faces[3] = (a, c, b, ax)

    def p(v: tuple[int, int, int]) -> str:
        return "( {} {} {} )".format(*v)

    lines = "".join(f"{p(a)} {p(b)} {p(c)} {tex} {ax} 0 1 1\n" for a, b, c, ax in faces)
    return "{\n" + lines + "}\n"


def add_world_brush(text: str, brush: str, label: str) -> str:
    """Insert a brush at the end of worldspawn (before its closing brace)."""
    end = text.index('}\n{\n"classname"', text.index('"classname" "worldspawn"'))
    return text[:end] + f"// brush: {label}\n" + brush + text[end:]


def drop_brush(text: str, label: str) -> str:
    return re.sub(rf"// brush: {label}\n\{{.*?\n\}}\n", "", text, flags=re.S)


def drop_entities(text: str, classname: str) -> str:
    return re.sub(rf'\{{\n"classname" "{classname}"\n.*?\n\}}\n', "", text, flags=re.S)


def fixtures(base: str) -> dict[str, str]:
    pillar = ((-64, -64, 0), (64, 64, 128))
    return {
        # leak: remove the north wall
        "broken_leak": drop_brush(base, "north"),
        # invalid brush: a pillar whose top face is wound backwards
        "broken_flipped": add_world_brush(base, box(*pillar, "DEV_WALL", flip_top=True), "pillar"),
        # off-grid: pillar edges at x = -60 / 68 (not multiples of 8)
        "broken_offgrid": add_world_brush(
            base, box((-60, -64, 0), (68, 64, 128), "DEV_WALL"), "pillar"
        ),
        # missing spawns: no T spawns at all
        "broken_nospawn": drop_entities(base, "info_player_deathmatch"),
        # stuck spawn: a CT spawn 8 units from the west wall (hull is 16 wide)
        "broken_stuck": base.replace('"origin" "-384 -128 36"', '"origin" "-504 -128 36"'),
        # narrow passage: a divider wall leaves a 48-unit gap at the north end (warning only)
        "narrow_gap": add_world_brush(
            base, box((-8, -512, 0), (8, 464, 256), "DEV_WALL"), "divider"
        ),
        # de_ map with one bomb target instead of two
        "de_onebomb": base + '{\n"classname" "info_bomb_target"\n"origin" "0 0 16"\n}\n',
    }


def main() -> None:
    base = SRC.read_text(encoding="utf-8")
    for name, text in fixtures(base).items():
        assert text != base, f"{name}: fixture did not change the map"
        d = OUT / name
        (d / "src").mkdir(parents=True, exist_ok=True)
        header = f"// FIXTURE {name}: generated by tests/fixtures/generate.py from test_box.map\n"
        (d / "src" / f"{name}.map").write_text(header + text, encoding="utf-8", newline="\n")
        (d / "validate.yaml").write_text(VALIDATE_YAML, encoding="utf-8", newline="\n")
        print(f"wrote {d}")


if __name__ == "__main__":
    main()
